def moving_average(xs, n):
    out = []
    for i in range(len(xs) - n):
        out.append(sum(xs[i:i + n]) / n)
    return out

from stats import moving_average

def test_three():
    assert moving_average([1, 2, 3, 4], 2) == [1.5, 2.5, 3.5]

def test_single():
    assert moving_average([5], 1) == [5.0]
